#include <iostream>
#include <array>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;

    constexpr long long MOD = 1000000007;
    array<long long, 4> dp{1, 0, 0, 0};

    for (long long step = 0; step < n; ++step) {
        array<long long, 4> next{};
        long long total = (dp[0] + dp[1] + dp[2] + dp[3]) % MOD;

        for (int state = 0; state < 4; ++state) {
            next[state] = (total - dp[state] + MOD) % MOD;
        }

        dp = next;
    }

    cout << dp[0] << '\n';
    return 0;
}

