#include <iostream>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    const long long MOD = 1000000007;
    long long n;
    cin >> n;

    long long dp[4] = {1, 0, 0, 0};

    for (long long step = 0; step < n; ++step) {
        long long next[4] = {};
        for (int from = 0; from < 4; ++from) {
            for (int to = 0; to < 4; ++to) {
                if (from != to) {
                    next[to] = (next[to] + dp[from]) % MOD;
                }
            }
        }
        for (int i = 0; i < 4; ++i)
            dp[i] = next[i];
    }

    cout << dp[0] << '\n';
    return 0;
